    ownerQueuedCollateralVault: TAccountMetas[7];
    userDestinationLiquidity: TAccountMetas[8];
    collateralTokenProgram: TAccountMetas[9];
    liquidityTokenProgram: TAccountMetas[10];
    withdrawTicket: TAccountMetas[11];
    withdrawTicketOwner: TAccountMetas[12];
    associatedTokenProgram: TAccountMetas[13];
    systemProgram: TAccountMetas[14];
    progressCallbackProgram?: TAccountMetas[15] | undefined;
    progressCallbackCustomAccount0?: TAccountMetas[16] | undefined;
