export function parseWithdrawQueuedLiquidityInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedWithdrawQueuedLiquidityInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 19) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 19,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === KAMINO_LENDING_PROGRAM_ADDRESS ? undefined : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      lendingMarket: getNextAccount(),
      lendingMarketAuthority: getNextAccount(),
      reserve: getNextAccount(),
      reserveLiquidityMint: getNextAccount(),
      reserveCollateralMint: getNextAccount(),
      reserveLiquiditySupply: getNextAccount(),
      ownerQueuedCollateralVault: getNextAccount(),
      userDestinationLiquidity: getNextAccount(),
      collateralTokenProgram: getNextAccount(),
      liquidityTokenProgram: getNextAccount(),
      withdrawTicket: getNextAccount(),
      withdrawTicketOwner: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      progressCallbackProgram: getNextOptionalAccount(),
      progressCallbackCustomAccount0: getNextOptionalAccount(),
      progressCallbackCustomAccount1: getNextOptionalAccount(),
      instructionSysvarAccount: getNextAccount(),
    },
    data: getWithdrawQueuedLiquidityInstructionDataDecoder().decode(instruction.data),
  };
}
